  Finset.fold op b f (insert a s) = op (f a) (Finset.fold op b f s)

theorem Finset.fold_congr.{u_1, u_2} {α : Type u_1} {β : Type u_2} {op : β → β → β}
  [hc : Std.Commutative op] [ha : Std.Associative op] {f : α → β} {b : β} {s : Finset α} {g : α → β}
  (H : ∀ x ∈ s, f x = g x) : Finset.fold op b f s = Finset.fold op b g s

theorem Finset.fold_singleton.{u_1, u_2} {α : Type u_1} {β : Type u_2} {op : β → β → β}
  [hc : Std.Commutative op] [ha : Std.Associative op] {f : α → β} {b : β} {a : α} :
  Finset.fold op b f {a} = op (f a) b

theorem Finset.fold_const.{u_1, u_2} {α : Type u_1} {β : Type u_2} {op : β → β → β}
  [hc : Std.Commutative op] [ha : Std.Associative op] {b : β} {s : Finset α}
  [hd : Decidable (s = ∅)] (c : β) (h : op c (op b c) = op b c) :
  Finset.fold op b (fun x => c) s = if s = ∅ then b else op b c

theorem Finset.fold_op_rel_iff_and.{u_1, u_2} {α : Type u_1} {β : Type u_2} {op : β → β → β}
  [hc : Std.Commutative op] [ha : Std.Associative op] {f : α → β} {b : β} {s : Finset α}
  {r : β → β → Prop} (hr : ∀ {x y z : β}, r x (op y z) ↔ r x y ∧ r x z) {c : β} :
  r c (Finset.fold op b f s) ↔ r c b ∧ ∀ x ∈ s, r c (f x)

theorem Finset.fold_hom.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {op : β → β → β}
  [hc : Std.Commutative op] [ha : Std.Associative op] {f : α → β} {b : β} {s : Finset α}
  {op' : γ → γ → γ} [Std.Commutative op'] [Std.Associative op'] {m : β → γ}
  (hm : ∀ (x y : β), m (op x y) = op' (m x) (m y)) :
  Finset.fold op' (m b) (fun x => m (f x)) s = m (Finset.fold op b f s)

theorem Finset.fold_disjUnion.{u_1, u_2} {α : Type u_1} {β : Type u_2} {op : β → β → β}
  [hc : Std.Commutative op] [ha : Std.Associative op] {f : α → β} {s₁ s₂ : Finset α} {b₁ b₂ : β}
  (h : Disjoint s₁ s₂) :
  Finset.fold op (op b₁ b₂) f (s₁.disjUnion s₂ h) =
    op (Finset.fold op b₁ f s₁) (Finset.fold op b₂ f s₂)

theorem Finset.fold_insert.{u_1, u_2} {α : Type u_1} {β : Type u_2} {op : β → β → β}
  [hc : Std.Commutative op] [ha : Std.Associative op] {f : α → β} {b : β} {s : Finset α} {a : α}
  [DecidableEq α] (h : a ∉ s) : Finset.fold op b f (insert a s) = op (f a) (Finset.fold op b f s)

theorem Finset.fold_union_inter.{u_1, u_2} {α : Type u_1} {β : Type u_2} {op : β → β → β}
  [hc : Std.Commutative op] [ha : Std.Associative op] {f : α → β} [DecidableEq α] {s₁ s₂ : Finset α}
  {b₁ b₂ : β} :
  op (Finset.fold op b₁ f (s₁ ∪ s₂)) (Finset.fold op b₂ f (s₁ ∩ s₂)) =
    op (Finset.fold op b₂ f s₁) (Finset.fold op b₁ f s₂)

theorem Finset.fold_map.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {op : β → β → β}
  [hc : Std.Commutative op] [ha : Std.Associative op] {f : α → β} {b : β} {g : γ ↪ α}
  {s : Finset γ} : Finset.fold op b f (Finset.map g s) = Finset.fold op b (f ∘ ⇑g) s

theorem Finset.disjiUnion_singleton.{u_1, u_2} {α : Type u_1} {β : Type u_2} {s : Finset α} {f : α → β}
  (hf : Function.Injective f) :
  s.disjiUnion (fun a => {f a}) ⋯ = Finset.map { toFun := f, inj' := hf } s

theorem Finset.fold_disjiUnion.{u_1, u_2, u_4} {α : Type u_1} {β : Type u_2} {f : α → β} {op : β → β → β}
  [hc : Std.Commutative op] [ha : Std.Associative op] {ι : Type u_4} {s : Finset ι}
  {t : ι → Finset α} {b : ι → β} {b₀ : β} (h : (↑s).PairwiseDisjoint t) :
  Finset.fold op (Finset.fold op b₀ b s) f (s.disjiUnion t h) =
    Finset.fold op b₀ (fun i => Finset.fold op (b i) f (t i)) s

theorem Finset.pairwiseDisjoint_filter.{u_1, u_2} {α : Type u_1} {β : Type u_2} {s : Finset α}
  {f : α → Finset β} (h : (↑s).PairwiseDisjoint f) (p : β → Prop) [DecidablePred p] :
  (↑s).PairwiseDisjoint fun a => Finset.filter p (f a)

theorem Finset.biUnion_congr.{u_1, u_2} {α : Type u_1} {β : Type u_2} {s₁ s₂ : Finset α}
  {t₁ t₂ : α → Finset β} [DecidableEq β] (hs : s₁ = s₂) (ht : ∀ a ∈ s₁, t₁ a = t₂ a) :
  s₁.biUnion t₁ = s₂.biUnion t₂

theorem Finset.map_disjiUnion.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {f : α ↪ β}
  {s : Finset α} {t : β → Finset γ} {h : (↑(Finset.map f s)).PairwiseDisjoint t} :
  (Finset.map f s).disjiUnion t h = s.disjiUnion (fun a => t (f a)) ⋯

theorem Finset.disjiUnion_map.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {s : Finset α}
  {t : α → Finset β} {f : β ↪ γ} {h : (↑s).PairwiseDisjoint t} :
  Finset.map f (s.disjiUnion t h) = s.disjiUnion (fun a => Finset.map f (t a)) ⋯

theorem Finset.filter_product.{u_1, u_2} {α : Type u_1} {β : Type u_2} {s : Finset α} {t : Finset β}
  (p : α → Prop) (q : β → Prop) [DecidablePred p] [DecidablePred q] :
  {x ∈ s ×ˢ t | p x.1 ∧ q x.2} = Finset.filter p s ×ˢ Finset.filter q t

theorem Finset.prodMap_image_product.{u_1, u_2, u_3, u_4} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {δ : Type u_4} [DecidableEq β] [DecidableEq δ] (f : α → β) (g : γ → δ) (s : Finset α)
  (t : Finset γ) : Finset.image (Prod.map f g) (s ×ˢ t) = Finset.image f s ×ˢ Finset.image g t

theorem Finset.prodMap_map_product.{u_1, u_2, u_3, u_4} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {δ : Type u_4} (f : α ↪ β) (g : γ ↪ δ) (s : Finset α) (t : Finset γ) :
  Finset.map (f.prodMap g) (s ×ˢ t) = Finset.map f s ×ˢ Finset.map g t

